using System;

namespace DrownedBell.Core
{
    /// <summary>
    /// Chapter IV, the Tidal Engine (map in EngineData.cs, generated by tools/engine_rooms.py from the room plates).
    /// Service Dock (lamp, model of the reversal mechanism), Flywheel Cradle (a Ballast Knight and the first governor
    /// latch), Condenser Bridge (vents, floor waves, the second latch, and a hatch to the optional Night Watch), Night
    /// Watch (three spring pads and the keeper's record), Governor Stair (a lift back to the dock once both latches are
    /// thrown, and a last lamp), Sea Gate (the Tidekeeper and the bypass wheel) and the Morning Nave (the drained
    /// first room: walking out ends the campaign).
    /// </summary>
    public static class TidalEngine
    {
        public static Level Build()
        {
            Level lv = Level.Parse(EngineData.Rows, EngineData.Rooms);
            lv.Chapter = Chapter.Engine;
            return lv;
        }

        public static Aabb PadBox(Vec2 pad) => new Aabb(new Vec2(pad.X, pad.Y + 0.25f), new Vec2(0.9f, 0.3f));

        static bool Near(Vec2 feet, Vec2 p, float reachX = 1f) => MathF.Abs(feet.X - p.X) < reachX && MathF.Abs(feet.Y - p.Y) < 1.25f;

        /// <summary>The Engine's stations, run by World each step: the dock model, the record, the lift and the last lamp.</summary>
        internal static void Stations(World w, bool up, ref bool upHeld)
        {
            Vec2 feet = w.Player.Body.Feet;
            Level lv = w.Level;
            if (!w.DockModelSeen && lv.DockModel is Vec2 model && Near(feet, model, 2.5f))
                w.SetEngineFlag(GameEventType.DockModelSeen, model);
            if (!w.EngineRecord && lv.Record is Vec2 record && Near(feet, record))
                w.SetEngineFlag(GameEventType.EngineRecordFound, record);
            if (!w.LiftOnline && w.LatchOpen[0] && w.LatchOpen[1])
                w.SetEngineFlag(GameEventType.LiftOnline, lv.StairLift.Value);
            if (lv.LiftLamp is Vec2 lamp && Near(feet, lamp) && (!w.RestLit || w.Player.Health < w.Player.MaxHealth))
                w.LightRestLamp(lamp);
            if (up && !upHeld && w.LiftOnline)
            {
                Vec2? target = Near(feet, lv.StairLift.Value) ? lv.Checkpoint : Near(feet, lv.Checkpoint) ? lv.StairLift.Value : (Vec2?)null;
                if (target.HasValue) w.Ride(target.Value);
            }
            upHeld = up;
        }

        // ---- input-only route, for the headless checks and the standalone QA pilot ---------------------------------------
        // It uses only ordinary inputs: move, jump, dash and aimed swings.

        /// <summary>Hop what is ahead: a pit (more than half a tile down) or a step up (up to three tiles) one tile and a bit in front.</summary>
        static bool HopAhead(World w, float move)
        {
            Body b = w.Player.Body;
            if (move == 0f || !b.Grounded) return false;
            float ahead = w.Level.FloorBelow(b.Pos.X + move * 1.15f, b.Bottom + 3.5f);
            return ahead > b.Bottom + 0.4f || ahead < b.Bottom - 0.5f;
        }

        static PumpMachine KnightIn(World w)
        {
            foreach (Enemy e in w.Foes)
                if (e is PumpMachine m && m.Kind == EnemyKind.Knight && m.Alive && m.Room == w.Room) return m;
            return null;
        }

        /// <summary>Stand behind the hammer (it only reaches the side it faces), then swing during the reset.</summary>
        static PlayerInput FoeTactic(World w, Enemy foe, MachineBeat? machine, KeeperBeat? keeper, KeeperAttack attack)
        {
            Vec2 feet = w.Player.Body.Feet;
            float dx = feet.X - foe.Home.X, side = dx >= 0f ? 1f : -1f, target = feet.X;
            bool dash = false, swing = false;
            bool windup = machine == MachineBeat.Brace || machine == MachineBeat.Strike ||
                          ((keeper == KeeperBeat.Windup || keeper == KeeperBeat.Strike) && (attack == KeeperAttack.Hammer || attack == KeeperAttack.Lane));
            bool recover = machine == MachineBeat.Recover || keeper == KeeperBeat.Recover;
            if (windup)
            {
                // Behind: opposite the facing the attack locked.
                float behind = foe.Home.X - foe.Facing * (foe is Tidekeeper ? 2.4f : 2.0f);
                bool alreadyBehind = (feet.X - foe.Home.X) * foe.Facing < -1.2f;
                if (!alreadyBehind) { target = behind; dash = MathF.Abs(behind - feet.X) > 1.5f; }
            }
            else if (recover)
            {
                target = foe.Home.X + side * 2.6f;
                swing = MathF.Abs(dx) < 3.4f;
            }
            else target = foe.Home.X + side * 3.4f;
            bool ripple = SoundingArchive.RippleComing(w);
            float move = ripple || MathF.Abs(target - feet.X) < 0.15f ? 0f : Mathx.Sign(target - feet.X);
            return new PlayerInput
            {
                MoveX = move, DashPressed = dash && w.Player.DashCooldown <= 0f,
                JumpPressed = ripple && w.Player.Body.Grounded, JumpHeld = true,
                AttackPressed = swing && !w.Player.Attacking, HasAim = swing, AimX = -dx,
            };
        }

        /// <summary>Latches and the wheel: walk up and swing the hook at them.</summary>
        internal static PlayerInput RouteInput(World w)
        {
            Body b = w.Player.Body;
            Vec2 feet = b.Feet;
            Level lv = w.Level;
            Tidekeeper keeper = w.Tidekeeper;
            if (keeper != null && keeper.Alive && keeper.Engaged) return FoeTactic(w, keeper, null, keeper.Beat, keeper.Attack);
            PumpMachine knight = KnightIn(w);
            if (knight != null && MathF.Abs(feet.X - knight.Home.X) < 9f)
                return FoeTactic(w, knight, knight.Beat, null, KeeperAttack.Hammer);

            float target = lv.Outlet.Value.X;
            bool strike = false;
            if (!w.LatchOpen[0]) { target = lv.Latches[0].X - 1.1f; strike = true; }
            else if (knight != null) target = knight.Home.X;
            else if (!w.LatchOpen[1]) { target = lv.Latches[1].X - 1.1f; strike = true; }
            else if (keeper != null && !keeper.Alive && !w.TideReversed) { target = lv.Wheel.Value.X - 1.1f; strike = true; }
            float move = MathF.Abs(target - feet.X) < 0.12f ? 0f : Mathx.Sign(target - feet.X);

            // Vents: wait at the edge of an island until the jet will stay quiet for the next 0.7 s.
            foreach (Vec2 vent in lv.Vents)
                if (MathF.Abs(feet.Y - vent.Y) < 2f && feet.X < vent.X - 1f && feet.X > vent.X - 3.2f && move > 0f &&
                    (SluiceWorks.VentAt(w.Time, vent) != VentState.Quiet || SluiceWorks.VentAt(w.Time + 0.7f, vent) != VentState.Quiet)) move = 0f;
            bool ripple = SoundingArchive.RippleComing(w);
            if (ripple) move = 0f;
            bool hop = ripple || HopAhead(w, move);
            bool swing = strike && move == 0f && b.Grounded;
            return new PlayerInput { MoveX = move, JumpPressed = hop && b.Grounded, JumpHeld = true, AttackPressed = swing && !w.Player.Attacking, HasAim = swing, AimX = 1f };
        }

        /// <summary>
        /// Crosses the Night Watch to the keeper's record by pogoing off the three spring pads: jump, down-swing on a pad,
        /// dash on to the next one, then up onto the platform. For the headless checks.
        /// </summary>
        internal static PlayerInput PadRoute(World w)
        {
            Body b = w.Player.Body;
            Vec2 feet = b.Feet;
            Level lv = w.Level;
            // The pads are listed top row first, so work from positions: the nearest pad not yet passed is the one to aim at,
            // unless the diver is over it and already rising from its bounce, in which case on to the next one.
            int aim = -1;
            for (int i = 0; i < lv.Pads.Count; i++)
                if (lv.Pads[i].X > feet.X - 1.1f && (aim < 0 || lv.Pads[i].X < lv.Pads[aim].X)) aim = i;
            bool airborne = !b.Grounded;
            bool rising = b.Vel.Y > 0.5f;
            if (aim >= 0 && MathF.Abs(feet.X - lv.Pads[aim].X) < 1.1f && rising && feet.Y > lv.Pads[aim].Y + 0.5f)
            {
                int after = -1;
                for (int i = 0; i < lv.Pads.Count; i++)
                    if (lv.Pads[i].X > lv.Pads[aim].X + 1f && (after < 0 || lv.Pads[i].X < lv.Pads[after].X)) after = i;
                aim = after;
            }
            float target = aim >= 0 ? lv.Pads[aim].X : lv.Record.Value.X;
            float move = MathF.Abs(target - feet.X) < 0.2f ? 0f : Mathx.Sign(target - feet.X);
            bool down = false, jump = false, dash = false;
            if (aim >= 0)
            {
                Vec2 pad = lv.Pads[aim];
                float above = feet.Y - pad.Y;
                if (airborne && MathF.Abs(feet.X - pad.X) < 1.1f && !rising && above > 0f && above < 1.35f) down = true;
                if (b.Grounded && MathF.Abs(feet.X - pad.X) < 4.2f) jump = true;
                // Dash at the top of the bounce: a dash flattens the climb, so it goes where the height has been spent.
                if (airborne && b.Vel.Y <= 1.5f && MathF.Abs(feet.X - pad.X) > 2.5f && !w.Player.AirDashUsed && w.Player.DashCooldown <= 0f) dash = true;
            }
            else
            {
                // Past the last pad: clear the platform edge, then walk to the record.
                if (b.Grounded && feet.Y < lv.Record.Value.Y - 0.5f && MathF.Abs(feet.X - 23f - lv.Rooms[w.Room].MinX) < 3.5f) jump = true;
                if (airborne && b.Vel.Y <= 1.5f && !w.Player.AirDashUsed && w.Player.DashCooldown <= 0f && feet.Y < lv.Record.Value.Y + 0.5f) dash = true;
            }
            return new PlayerInput
            {
                MoveX = move, JumpPressed = jump, JumpHeld = jump || airborne, DashPressed = dash,
                Down = down, AttackPressed = down && !w.Player.Attacking,
            };
        }

        /// <summary>The hook strikes the latches, the bypass wheel and the spring pads.</summary>
        internal static void OnPlayerHit(World w, Aabb hit, ref bool connected)
        {
            Level lv = w.Level;
            for (int i = 0; i < lv.Latches.Count && i < w.LatchOpen.Length; i++)
                if (!w.LatchOpen[i] && hit.Overlaps(World.WinchBox(lv.Latches[i])))
                {
                    w.OpenLatch(i);
                    connected = true;
                }
            if (lv.Wheel is Vec2 wheel && w.Tidekeeper != null && !w.Tidekeeper.Alive && !w.TideReversed && hit.Overlaps(World.WinchBox(wheel)))
            {
                w.ReverseTide();
                connected = true;
            }
            // A down-swing on a spring pad bounces the diver and gives back the air dash, like a pogo off an enemy.
            if (w.Player.Attack == AttackDir.Down)
                foreach (Vec2 pad in lv.Pads)
                    if (hit.Overlaps(PadBox(pad)))
                    {
                        if (!w.Player.SwingConnected) w.Emit(GameEventType.PadBounce, pad);
                        connected = true;
                    }
        }
    }
}
